import {
	Component,
	Element,
	Event,
	EventEmitter,
	Method,
	h,
} from "@stencil/core";

interface Touched {
	name?: boolean;
}
interface FormControl {
	tag: string;
	serialize: (el: HTMLElement, formData: FormData) => void;
	click?: (event: MouseEvent) => void;
	keyDown?: (event: KeyboardEvent) => void;
}

type FormElement =
	| HTMLInputElement
	| HTMLSelectElement
	| HTMLTextAreaElement
	| HTMLHbrInputElement
	| HTMLHbrCheckboxElement
	| HTMLHbrRadioElement
	| HTMLHbrTextareaElement
	| HTMLHbrSliderElement;
/**
 * @since 0.0.11
 * @status experimental
 *
 * @slot - The form's content.
 *
 * @part base - The component's base wrapper.
 */

@Component({
	tag: "hbr-form",
	styleUrl: "form.scss",
	shadow: true,
})
export class Form {
	formControls: FormControl[];
	supportedComponentsMap = {};
	validate = false;
	@Element() host: HTMLHbrFormElement;

	/** deprecated */
	@Event({ eventName: "hbr-submit" }) hbrSubmit: EventEmitter<{
		formData: FormData;
		formControls: HTMLElement[];
	}>;

	/**
	 * firing once when component load
	 */
	@Event({ eventName: "hbr-init" }) hbrInit: EventEmitter;

	componentWillLoad() {
		this.hbrInit.emit();
	}

	connectedCallback() {
		this.getFormControls = this.getFormControls.bind(this);
		this.formControls = [
			{
				tag: "button",
				serialize: (el: HTMLButtonElement, formData) =>
					el.name ? formData.append(el.name, el.value) : null,
				click: (event) => {
					const target = event.target as HTMLButtonElement;
					if (target.type === "submit") {
						// this.submit();
					}
				},
			},
			{
				tag: "input",
				serialize: (el: HTMLInputElement, formData) => {
					if (!el.name) {
						return;
					}

					if (el.type === "checkbox" || el.type === "radio") {
						return;
					}

					if (el.type === "file") {
						Array.from(el.files).map((file) => formData.append(el.name, file));
						return;
					}

					formData.append(el.name, el.value);
				},
				click: (event) => {
					const target = event.target as HTMLInputElement;
					if (target.type === "submit") {
						// this.submit();
					}
				},
				keyDown: (event) => {
					const target = event.target as HTMLInputElement;
					if (
						event.key === "Enter" &&
						!event.defaultPrevented &&
						!["checkbox", "file", "radio"].includes(target.type)
					) {
						// this.submit();
					}
				},
			},
			{
				tag: "select",
				serialize: (el: HTMLSelectElement, formData) => {
					if (el.name) {
						if (el.multiple) {
							const selectedOptions = Array.from(
								el.querySelectorAll("option:checked"),
							);
							if (selectedOptions.length) {
								selectedOptions.map((option: HTMLOptionElement) =>
									formData.append(el.name, option.value),
								);
							} else {
								formData.append(el.name, "");
							}
						} else {
							formData.append(el.name, el.value);
						}
					}
				},
			},
			{
				tag: "hbr-button",
				serialize: (el: HTMLHbrButtonElement, formData) =>
					el.name ? formData.append(el.name, el.value) : null,
				click: (event) => {
					const target = event.target as HTMLHbrButtonElement;
					if (target.submit) {
						// this.submit();
					}
				},
			},
			{
				tag: "hbr-checkbox",
				serialize: (el: HTMLHbrCheckboxElement, formData) =>
					el.name ? formData.append(el.name, `${el.checked}`) : null,
			},
			{
				tag: "hbr-time-picker",
				serialize: (timePickerElement: HTMLElement, formData) => {
					const el = timePickerElement as unknown as HTMLHbrTimePickerElement;
					el.name ? formData.append(el.name, el.value) : null;
				},
			},
			{
				tag: "hbr-date-picker",
				serialize: (datePickerElement: HTMLElement, formData) => {
					const el = datePickerElement as unknown as HTMLHbrDatePickerElement;
					if (Array.isArray(el.value) || el.range) {
						const rangeValue = Array.from(el.value);
						if (rangeValue.length) {
							rangeValue.map((value) => formData.append(el.name, value));
						} else {
							formData.append(el.name, "");
						}
					} else {
						el.name ? formData.append(el.name, el.value) : null;
					}
				},
			},
			{
				tag: "hbr-input",
				serialize: (el: HTMLHbrInputElement, formData) =>
					el.name ? formData.append(el.name, el.value) : null,
				keyDown: (event) => {
					if (event.key === "Enter" && !event.defaultPrevented) {
						// this.submit();
					}
				},
			},
			{
				tag: "hbr-radio",
				serialize: (el: HTMLHbrRadioElement, formData) =>
					el.name ? formData.append(el.name, `${el.checked}`) : null,
			},
			{
				tag: "hbr-slider",
				serialize: (el: HTMLHbrSliderElement, formData) => {
					if (el.name) {
						formData.append(el.name, "");
					}
				},
			},
			{
				tag: "hbr-select",
				serialize: (el: HTMLHbrSelectElement, formData) => {
					if (el.name) {
						if (el.variant === "multiple") {
							const selectedOptions = Array.from(el.value);
							if (selectedOptions.length) {
								selectedOptions.map((value) => formData.append(el.name, value));
							} else {
								formData.append(el.name, "");
							}
						} else {
							formData.append(el.name, `${el.value}`);
						}
					}
				},
			},
			{
				tag: "hbr-switch",
				serialize: (el: HTMLHbrSwitchElement, formData) =>
					el.name ? formData.append(el.name, `${el.checked}`) : null,
			},
			{
				tag: "hbr-textarea",
				serialize: (el: HTMLHbrTextareaElement, formData) =>
					el.name ? formData.append(el.name, el.value) : null,
			},
			{
				tag: "textarea",
				serialize: (el: HTMLTextAreaElement, formData) =>
					el.name ? formData.append(el.name, el.value) : null,
			},
		];
		this.handleClick = this.handleClick.bind(this);
		this.handleKeyDown = this.handleKeyDown.bind(this);
		this.runSchema = this.runSchema.bind(this);
		this.serializeElement = this.serializeElement.bind(this);
		this.updateSupportedComponentsMap =
			this.updateSupportedComponentsMap.bind(this);
		this.updateSupportedComponentsMap();
	}

	/** Serializes all form controls elements and returns a `FormData` object. */
	@Method()
	async getFormData() {
		const formData = new FormData();
		const formControls = await this.getFormControls();

		formControls.map((el) => this.serializeElement(el, formData));

		return formData;
	}

	/** extend more form controls elements, please see the interface of returning array of formControl  */
	@Method()
	async extendFormControls(data) {
		Array.isArray(data) && this.formControls.push(...data);
		this.updateSupportedComponentsMap();
		return this.formControls;
	}

	@Method()
	async getFormControlsThatReport() {
		const formControls = await this.getFormControls();
		return formControls.filter(
			(el): el is FormElement =>
				typeof (el as FormElement).reportValidity === "function",
		) as Array<FormElement>;
	}

	/** set form element to touched or untouched, params interface {elementName: boolean}  */
	@Method()
	async setTouched(touched = {}) {
		const formControls = await this.getFormControls();
		const result = {};
		for (const el of formControls) {
			// @ts-ignore
			const name = el?.name;
			if (name) {
				if (name in touched) {
					if (touched[name]) {
						el?.setAttribute("data-touched", "true");
					} else if (touched[name] === false) {
						el?.removeAttribute("data-touched");
					}
				}
				if (!result[name]) result[name] = {};
				result[name].touched = touched[name];
			}
		}
		return result;
	}

	/** get form elements and form touched state */
	@Method()
	async getTouched() {
		const formControls = await this.getFormControls();
		const result = {};
		let isFormTouched = false;
		for (const el of formControls) {
			// @ts-ignore
			const name = el?.name;
			if (name) {
				if (!result[name]) result[name] = {};
				if (el.hasAttribute("data-touched")) {
					result[name].touched = true;
					isFormTouched = true;
				} else {
					result[name].touched = false;
				}
			}
		}
		return { result, isFormTouched };
	}

	/** set form element value to touched or untouched, params inteface {elementName: {key: string<elementName>, value: any}}  */
	@Method()
	async setValues(values) {
		const formControls = await this.getFormControls();

		for (const el of formControls) {
			// @ts-ignore
			const name = el?.name;
			const entries = values[name];
			if (!entries) continue;
			if (name in values && entries) {
				el[entries.key] = entries.value;
			}
		}
	}

	/** Gets all form control elements (native and custom). */
	@Method()
	async getFormControls() {
		const childrenList = Array.from(this.host.querySelectorAll("*"));
		const tags = this.formControls.map((control) => control.tag);
		return childrenList.filter((el) =>
			tags.includes(el.tagName.toLowerCase()),
		) as HTMLElement[];
	}

	/** set multiple conditions against the element, each condition hold relative message */
	@Method()
	async runSchema(schema, touched: Touched = {}) {
		const formControls = await this.getFormControls();

		const result = {};
		const _touched = {};
		const _error = {};
		const _condition = {};
		let isFormValid = true;
		for (const el of formControls) {
			if (el) {
				// @ts-ignore
				const name = el?.name || el?.getAttribute("name");
				if (!name) continue;
				let conditions = [];
				let error = false;
				if (schema[name]) {
					conditions = (schema[name]?.conditions || []).map((con) => {
						const condition = con?.condition({
							element: el,
							elements: formControls,
						});
						if (condition) {
							isFormValid = false;
							error = true;
						}
						return {
							...con,
							show: condition,
						};
					});
				}
				if (name in touched) {
					if (touched[name]) {
						el?.setAttribute("data-touched", "true");
					} else if (touched[name] === false) {
						el?.removeAttribute("data-touched");
					}
				}
				const isTouched = touched[name] || el?.hasAttribute("data-touched");
				_touched[name] = isTouched;
				_error[name] = error;
				_condition[name] = conditions;
				result[name] = { conditions, error, touched: isTouched };
			}
		}
		const formData = await this.getFormData();

		return {
			isFormValid,
			result,
			formData,
			touched: _touched,
			error: _error,
			condition: _condition,
		};
	}

	/**
    deprecated
   */
	@Method()
	async submit() {
		const formData = await this.getFormData();
		const formControls = await this.getFormControls();
		const formControlsThatReport = formControls.filter(
			(el: FormElement) =>
				typeof (el as FormElement).reportValidity === "function",
		) as Array<FormElement>;

		if (this.validate) {
			for (const el of formControlsThatReport) {
				const isValid = await el.reportValidity();

				if (!isValid) {
					return false;
				}
			}
		}

		this.hbrSubmit.emit({ formData, formControls });
		return true;
	}

	getBoolean = (value: string | FormDataEntryValue) => {
		if (value === "true") return true;
		if (value === "false") return false;
		return value;
	};
	/**
	 * Serializes a form and returns a plain object. If a form control with the same name appears more than once, the
	 * property will be converted to an array.
	 */
	@Method()
	async serialize(data: FormData) {
		const formData = data;
		const object: Record<string, unknown> = {};

		formData?.forEach((value, key) => {
			const _value = this.getBoolean(value);
			if (Reflect.has(object, key)) {
				const entry = object[key];
				if (Array.isArray(entry)) {
					entry.push(_value);
				} else {
					object[key] = [object[key], _value];
				}
			} else {
				object[key] = _value;
			}
		});

		return object;
	}

	updateSupportedComponentsMap = () => {
		this.supportedComponentsMap = this.formControls.reduce((pre, item) => {
			pre[item.tag] = true;
			return pre;
		}, {});
	};

	handleClick(event: MouseEvent) {
		const target = event.target as HTMLElement;
		const tag = target.tagName.toLowerCase();

		for (const formControl of this.formControls) {
			if (formControl.tag === tag && formControl.click) {
				formControl.click(event);
			}
		}
	}

	handleKeyDown(event: KeyboardEvent) {
		const target = event.target as HTMLElement;
		const tag = target.tagName.toLowerCase();

		for (const formControl of this.formControls) {
			if (formControl.tag === tag && formControl.keyDown) {
				formControl.keyDown(event);
			}
		}
	}

	serializeElement(el: HTMLElement, formData: FormData) {
		const tag = el.tagName.toLowerCase();

		for (const formControl of this.formControls) {
			if (formControl.tag === tag) {
				return formControl.serialize(el, formData);
			}
		}

		return null;
	}

	render() {
		return (
			<div
				part="base"
				class="form"
				role="form"
				onClick={this.handleClick}
				onKeyDown={this.handleKeyDown}
				onFocusout={(e) => {
					const target = e?.target as HTMLElement;
					const tag = target?.tagName?.toLowerCase();
					this.supportedComponentsMap[tag] &&
						target?.setAttribute("data-touched", "true");
				}}
			>
				<slot />
			</div>
		);
	}
}
